    assert!(result.is_err(), "에러를 감지해야 함");
}
```

#### 패턴 2: AST 검증

```rust
#[test]
fn test_parse_ast_structure() {
    let source = "fn add(x: i32, y: i32) -> i32 { return x + y; }";
    let lexer = SecureLexer::new(source).unwrap();
    let tokens = lexer.tokenize().unwrap();
    let parser = Parser::new(tokens).unwrap();
    let program = parser.parse().unwrap();

    // AST 구조 검증
    assert_eq!(program.definitions.len(), 1);
    match &program.definitions[0] {
        Definition::Function { name, params, body } => {
            assert_eq!(name, "add");
            assert_eq!(params.len(), 2);
            assert_eq!(params[0], "x");
            assert_eq!(params[1], "y");
            assert!(body.len() > 0);
        }
        _ => panic!("함수 정의여야 함"),
    }
}
```

#### 패턴 3: 성능 측정

```rust
#[test]
fn test_performance_parsing_speed() {
    let source = "fn test() -> i32 { return 1 + 2 + 3 + 4 + 5; }";
    let lexer = SecureLexer::new(source).unwrap();
    let tokens = lexer.tokenize().unwrap();

    let start = std::time::Instant::now();
    let parser = Parser::new(tokens).unwrap();
    let _ = parser.parse();
    let elapsed = start.elapsed();

    println!("파싱 시간: {:?}", elapsed);
    assert!(elapsed.as_millis() < 10, "성능 기준 초과");
}
```

#### 패턴 4: 여러 케이스

```rust
#[test]
fn test_parse_operator_precedence_multiple_cases() {
    let test_cases = vec![
        ("1 + 2 * 3", true),       // 유효
        ("(1 + 2) * 3", true),     // 유효
        ("1 + 2 +", false),        // 무효
    ];

    for (source, should_pass) in test_cases {
        let source = format!("fn test() -> i32 {{ return {}; }}", source);
        let lexer = SecureLexer::new(&source).unwrap();
        let tokens = lexer.tokenize().unwrap();
        let parser = Parser::new(tokens).unwrap();
        let result = parser.parse();

        if should_pass {
            assert!(result.is_ok(), "유효한 소스가 실패: {}", source);
        } else {
            assert!(result.is_err(), "무효한 소스가 통과: {}", source);
        }
    }
}
```

