use std::collections::HashMap;
use crate::types::Type;

/// 심볼 테이블에 저장되는 심볼 정보
#[derive(Debug, Clone)]
pub struct Symbol {
    pub name: String,
    pub type_: Type,
    pub is_mutable: bool,
    pub scope_level: usize,
}

impl Symbol {
    pub fn new(name: String, type_: Type, is_mutable: bool, scope_level: usize) -> Self {
        Symbol {
            name,
            type_,
            is_mutable,
            scope_level,
        }
    }
}

/// 변수, 함수 등의 심볼을 관리하는 테이블
pub struct SymbolTable {
    /// 스코프 스택 (가장 안쪽이 맨 뒤)
    scopes: Vec<HashMap<String, Symbol>>,
}

impl SymbolTable {
    /// 새로운 심볼 테이블을 생성합니다 (글로벌 스코프 포함)
    pub fn new() -> Self {
        let mut table = SymbolTable {
            scopes: vec![],
        };
        table.enter_scope();  // 글로벌 스코프
        table
    }

    /// 새로운 스코프에 진입합니다
    pub fn enter_scope(&mut self) {
        self.scopes.push(HashMap::new());
    }

    /// 현재 스코프를 종료합니다
    pub fn exit_scope(&mut self) {
        if self.scopes.len() > 1 {
            self.scopes.pop();
        }
    }

    /// 현재 스코프 깊이를 반환합니다
    pub fn current_scope_level(&self) -> usize {
        self.scopes.len() - 1
    }

    /// 현재 스코프에 심볼을 정의합니다
    pub fn define(
        &mut self,
        name: String,
        type_: Type,
        is_mutable: bool,
    ) -> Result<(), String> {
        let scope_level = self.current_scope_level();

        if let Some(scope) = self.scopes.last_mut() {
            // 현재 스코프에만 있는지 확인
            if scope.contains_key(&name) {
                return Err(format!("중복된 변수 정의: '{}'", name));
            }

            scope.insert(
                name.clone(),
                Symbol::new(name, type_, is_mutable, scope_level),
            );
            Ok(())
        } else {
            Err("스코프 없음".to_string())
        }
    }

    /// 심볼을 조회합니다 (현재 스코프부터 역순)
    pub fn lookup(&self, name: &str) -> Option<Symbol> {
        for scope in self.scopes.iter().rev() {
            if let Some(symbol) = scope.get(name) {
                return Some(symbol.clone());
            }
        }
        None
    }

    /// 심볼이 현재 스코프에만 정의되어 있는지 확인합니다
    pub fn lookup_current_scope(&self, name: &str) -> Option<Symbol> {
        if let Some(scope) = self.scopes.last() {
            scope.get(name).cloned()
        } else {
            None
        }
    }

    /// 심볼의 타입을 조회합니다
    pub fn get_type(&self, name: &str) -> Option<Type> {
        self.lookup(name).map(|s| s.type_)
    }

    /// 심볼이 변경 가능한지 확인합니다
    pub fn is_mutable(&self, name: &str) -> Option<bool> {
        self.lookup(name).map(|s| s.is_mutable)
    }

    /// 모든 스코프를 초기화합니다 (글로벌 스코프만 유지)
    pub fn reset(&mut self) {
        self.scopes.clear();
        self.enter_scope();
    }

    /// 현재 스코프의 심볼들을 반환합니다
    pub fn current_symbols(&self) -> Vec<Symbol> {
        if let Some(scope) = self.scopes.last() {
            scope.values().cloned().collect()
        } else {
            vec![]
        }
    }

    /// 모든 스코프의 심볼들을 반환합니다
    pub fn all_symbols(&self) -> Vec<Symbol> {
        let mut symbols = vec![];
        for scope in &self.scopes {
            symbols.extend(scope.values().cloned());
        }
        symbols
    }
}

impl Default for SymbolTable {
    fn default() -> Self {
        Self::new()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_symbol_table_new() {
        let table = SymbolTable::new();
        assert_eq!(table.current_scope_level(), 0);
    }

    #[test]
    fn test_symbol_define() {
        let mut table = SymbolTable::new();
        let result = table.define("x".to_string(), Type::Integer, true);
        assert!(result.is_ok());
    }

    #[test]
    fn test_symbol_duplicate_definition() {
        let mut table = SymbolTable::new();
        table.define("x".to_string(), Type::Integer, true).unwrap();
        let result = table.define("x".to_string(), Type::Float, true);
        assert!(result.is_err());
    }

    #[test]
    fn test_symbol_lookup() {
        let mut table = SymbolTable::new();
        table.define("x".to_string(), Type::Integer, true).unwrap();
        let symbol = table.lookup("x");
        assert!(symbol.is_some());
        assert_eq!(symbol.unwrap().type_, Type::Integer);
    }

    #[test]
    fn test_symbol_lookup_undefined() {
        let table = SymbolTable::new();
        let symbol = table.lookup("undefined");
        assert!(symbol.is_none());
    }

    #[test]
    fn test_scope_enter_exit() {
        let mut table = SymbolTable::new();
        assert_eq!(table.current_scope_level(), 0);

        table.enter_scope();
        assert_eq!(table.current_scope_level(), 1);

        table.exit_scope();
        assert_eq!(table.current_scope_level(), 0);
    }

    #[test]
    fn test_scope_isolation() {
        let mut table = SymbolTable::new();
        table.define("x".to_string(), Type::Integer, true).unwrap();

        table.enter_scope();
        table.define("y".to_string(), Type::String, false).unwrap();

        // y는 현재 스코프에만 존재
        assert!(table.lookup_current_scope("y").is_some());

        table.exit_scope();

        // y는 글로벌 스코프에 없음
        assert!(table.lookup_current_scope("y").is_none());

        // x는 여전히 조회 가능
        assert!(table.lookup("x").is_some());
    }

    #[test]
    fn test_scope_shadowing() {
        let mut table = SymbolTable::new();
        table.define("x".to_string(), Type::Integer, true).unwrap();

        table.enter_scope();
        // 같은 이름으로 새로운 정의
        table.define("x".to_string(), Type::String, false).unwrap();

        // 내부 스코프의 x를 조회
        let symbol = table.lookup("x");
        assert_eq!(symbol.unwrap().type_, Type::String);

        table.exit_scope();

        // 외부 스코프의 x를 조회
        let symbol = table.lookup("x");
        assert_eq!(symbol.unwrap().type_, Type::Integer);
    }

    #[test]
    fn test_symbol_get_type() {
        let mut table = SymbolTable::new();
        table.define("x".to_string(), Type::Float, true).unwrap();
        assert_eq!(table.get_type("x"), Some(Type::Float));
        assert_eq!(table.get_type("undefined"), None);
    }

    #[test]
    fn test_symbol_is_mutable() {
        let mut table = SymbolTable::new();
        table.define("x".to_string(), Type::Integer, true).unwrap();
        table.define("y".to_string(), Type::String, false).unwrap();

        assert_eq!(table.is_mutable("x"), Some(true));
        assert_eq!(table.is_mutable("y"), Some(false));
        assert_eq!(table.is_mutable("undefined"), None);
    }

    #[test]
    fn test_symbol_table_reset() {
        let mut table = SymbolTable::new();
        table.define("x".to_string(), Type::Integer, true).unwrap();
        table.enter_scope();
        table.define("y".to_string(), Type::String, false).unwrap();

        table.reset();
        assert_eq!(table.current_scope_level(), 0);
        assert!(table.lookup("x").is_none());
        assert!(table.lookup("y").is_none());
    }

    #[test]
    fn test_symbol_table_all_symbols() {
        let mut table = SymbolTable::new();
        table.define("x".to_string(), Type::Integer, true).unwrap();
        table.define("y".to_string(), Type::String, false).unwrap();

        let symbols = table.all_symbols();
        assert_eq!(symbols.len(), 2);
    }
}
