// Phase 3 Stage 1: 기본 타입 시스템 테스트
// 15개의 기본 타입 검사 테스트

use fv_lang::ast::*;
use fv_lang::type_checker::TypeChecker;
use fv_lang::types::Type;
use fv_lang::symbols::SymbolTable;

// ============================================================================
// Stage 1: 기본 타입 시스템 테스트 (15개)
// ============================================================================

#[test]
fn test_type_integer_literal() {
    let mut checker = TypeChecker::new();
    let expr = Expression::Literal(Literal::Integer(42));
    assert_eq!(checker.check_expression(&expr), Ok(Type::Integer));
}

#[test]
fn test_type_float_literal() {
    let mut checker = TypeChecker::new();
    let expr = Expression::Literal(Literal::Float(3.14));
    assert_eq!(checker.check_expression(&expr), Ok(Type::Float));
}

#[test]
fn test_type_string_literal() {
    let mut checker = TypeChecker::new();
    let expr = Expression::Literal(Literal::String("hello".to_string()));
    assert_eq!(checker.check_expression(&expr), Ok(Type::String));
}

#[test]
fn test_type_boolean_literal() {
    let mut checker = TypeChecker::new();
    let expr = Expression::Literal(Literal::Boolean(true));
    assert_eq!(checker.check_expression(&expr), Ok(Type::Boolean));
}

#[test]
fn test_type_undefined_variable() {
    let mut checker = TypeChecker::new();
    let expr = Expression::Variable("undefined".to_string());
    assert!(checker.check_expression(&expr).is_err());
}

#[test]
fn test_type_arithmetic_integers() {
    let mut checker = TypeChecker::new();
    let expr = Expression::BinaryOp {
        op: "Plus".to_string(),
        left: Box::new(Expression::Literal(Literal::Integer(1))),
        right: Box::new(Expression::Literal(Literal::Integer(2))),
    };
    assert_eq!(checker.check_expression(&expr), Ok(Type::Integer));
}

#[test]
fn test_type_arithmetic_floats() {
    let mut checker = TypeChecker::new();
    let expr = Expression::BinaryOp {
        op: "Slash".to_string(),
        left: Box::new(Expression::Literal(Literal::Float(10.0))),
        right: Box::new(Expression::Literal(Literal::Float(2.5))),
    };
    assert_eq!(checker.check_expression(&expr), Ok(Type::Float));
}

#[test]
fn test_type_arithmetic_mixed_numeric() {
    let mut checker = TypeChecker::new();
    let expr = Expression::BinaryOp {
        op: "Plus".to_string(),
        left: Box::new(Expression::Literal(Literal::Integer(1))),
        right: Box::new(Expression::Literal(Literal::Float(2.5))),
    };
    // i32 + f64 → f64
    assert_eq!(checker.check_expression(&expr), Ok(Type::Float));
}

#[test]
fn test_type_arithmetic_type_error() {
    let mut checker = TypeChecker::new();
    let expr = Expression::BinaryOp {
        op: "Plus".to_string(),
        left: Box::new(Expression::Literal(Literal::Integer(1))),
        right: Box::new(Expression::Literal(Literal::String("hello".to_string()))),
    };
    assert!(checker.check_expression(&expr).is_err());
}

#[test]
fn test_type_comparison() {
    let mut checker = TypeChecker::new();
    let expr = Expression::BinaryOp {
        op: "Eq".to_string(),
        left: Box::new(Expression::Literal(Literal::Integer(1))),
        right: Box::new(Expression::Literal(Literal::Integer(2))),
    };
    assert_eq!(checker.check_expression(&expr), Ok(Type::Boolean));
}

#[test]
fn test_type_logical_and() {
    let mut checker = TypeChecker::new();
    let expr = Expression::BinaryOp {
        op: "And".to_string(),
        left: Box::new(Expression::Literal(Literal::Boolean(true))),
        right: Box::new(Expression::Literal(Literal::Boolean(false))),
    };
    assert_eq!(checker.check_expression(&expr), Ok(Type::Boolean));
}

#[test]
fn test_type_logical_operation_error() {
    let mut checker = TypeChecker::new();
    let expr = Expression::BinaryOp {
        op: "And".to_string(),
        left: Box::new(Expression::Literal(Literal::Integer(1))),
        right: Box::new(Expression::Literal(Literal::Boolean(true))),
    };
    assert!(checker.check_expression(&expr).is_err());
}

#[test]
fn test_type_unary_not() {
    let mut checker = TypeChecker::new();
    let expr = Expression::UnaryOp {
        op: "Not".to_string(),
        operand: Box::new(Expression::Literal(Literal::Boolean(true))),
    };
    assert_eq!(checker.check_expression(&expr), Ok(Type::Boolean));
}

#[test]
fn test_type_unary_minus() {
    let mut checker = TypeChecker::new();
    let expr = Expression::UnaryOp {
        op: "Minus".to_string(),
        operand: Box::new(Expression::Literal(Literal::Integer(42))),
    };
    assert_eq!(checker.check_expression(&expr), Ok(Type::Integer));
}

#[test]
fn test_type_if_expression() {
    let mut checker = TypeChecker::new();
    let expr = Expression::IfExpr {
        condition: Box::new(Expression::Literal(Literal::Boolean(true))),
        then_expr: Box::new(Expression::Literal(Literal::Integer(1))),
        else_expr: Some(Box::new(Expression::Literal(Literal::Integer(2)))),
    };
    assert_eq!(checker.check_expression(&expr), Ok(Type::Integer));
}

